function libraryMarkup(){return `<section class="interior-library" aria-label="Begehbares Borges-Interieur"><div id="interior-stage" class="interior-stage" tabindex="0" aria-label="Bibliothek in Innenansicht. Pfeile oder WASD zum Gehen, Maus ziehen zum Umsehen."><div id="interior-canvas"></div><div id="interior-hitbooks"></div>${librarianStageMarkup()}<div class="interior-vignette" aria-hidden="true"></div><div class="interior-top"><div><span class="eyebrow">Die Bibliothek von Babel</span><h1 id="interior-room-title">Die Bibliothek</h1><span id="interior-position">Galerie 00</span></div><div class="interior-actions"><button id="interior-home">Zu Borges</button><label class="sr-only" for="interior-find">Buch im Regal finden</label><input id="interior-find" type="search" placeholder="Buch im Regal finden …" aria-label="Buch im Regal finden"><button id="interior-help-toggle" aria-expanded="false">Wie wandeln?</button><label class="sr-only" for="interior-room-select">Galerie wählen</label><select id="interior-room-select">${rooms.map(r=>`<option value="${r[0]}">${r[1]} · ${esc(r[2])}</option>`).join('')}</select></div></div><div class="interior-whisper" id="interior-whisper">Ein Buchrücken leuchtet im Regal. Zieh ihn heraus.</div><div class="interior-controls"><button data-walk="left" aria-label="Nach links gehen">←</button><button data-walk="forward" aria-label="Vorwärts gehen">↑</button><button data-walk="back" aria-label="Rückwärts gehen">↓</button><button data-walk="right" aria-label="Nach rechts gehen">→</button><button data-turn="left" aria-label="Nach links schauen">↶</button><button data-turn="right" aria-label="Nach rechts schauen">↷</button></div><div class="interior-foot"><span id="interior-found">${(state.data.foundBooks||[]).length} Bücher entdeckt</span><span>WASD / Pfeile: gehen · Türen anklicken oder hindurchgehen</span><button id="interior-next">Durchgang zur nächsten Galerie →</button></div><div id="interior-help" class="interior-help" hidden><h2>Du stehst zwischen Bücherwänden.</h2><p><b>Umsehen:</b> Mit gedrückter Maustaste ziehen. Am linken und rechten Bildrand dreht sich dein Blick langsam.</p><p><b>Gehen:</b> WASD oder Pfeiltasten; auf dem Bildschirm die Richtungstasten gedrückt halten. Das Mausrad geht vor und zurück.</p><p><b>Durchgänge:</b> Folge dem Gang in der Bücherwand oder nutze „Nächste Galerie“. Über die Galeriewahl erreichst du jeden Raum direkt.</p><p><b>Lesen:</b> Fahre über beschriftete Buchrücken und ziehe mit einem Klick einen Band heraus. Der Band öffnet sich vor dir. „Weiterblättern“ führt durch die Buchseiten; Escape stellt ihn zurück.</p><p>Im Ruhemodus bewegt sich der Blick nur, wenn du selbst ziehst oder die Tasten benutzt.</p><button id="interior-help-close">Zurück zur Bibliothek</button></div></div><section id="reading-volume" class="reading-volume" aria-label="Aufgeschlagenes Buch" hidden><div class="volume-cover"></div><div class="volume-leaf leaf-under-one"></div><div class="volume-leaf leaf-under-two"></div><div class="volume-spread"><aside class="volume-left"><div class="volume-running">BABEL / LEKTÜREN UND FUNDSTÜCKE</div><span id="shelf-origin" class="volume-origin"></span><h2 id="shelf-title"></h2><div id="volume-frontispiece" class="volume-frontispiece"></div><p id="volume-intro"></p><div class="volume-imprint">In dieser Bibliothek ist ein Fund<br>noch keine Antwort.</div><div class="volume-page-number">I</div></aside><div class="volume-gutter" aria-hidden="true"></div><article class="volume-right"><div class="volume-running" id="volume-running-right"></div><div id="shelf-content" class="book-paper" tabindex="0"></div><div id="volume-guide-nav" class="volume-guide-nav"></div><div class="volume-page-turn"><button id="volume-prev" aria-label="Zurückblättern">← Zurückblättern</button><span id="volume-page">II</span><button id="volume-next" aria-label="Weiterblättern">Weiterblättern →</button></div></article></div><button id="shelf-close" class="volume-bookmark">Buch zurückstellen <span>×</span></button></section><span class="sr-only" id="interior-status" role="status"></span></section>`;}
